#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  int  gr,fr;  enum EDirect eDir;  RGBTRIPLE rgb[3];//0-фон,1-свет,2-тьма  } Queue_DnoE;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void SetT(RGBTRIPLE& val,COLORREF color);//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void GradientEllipse( HDC hDC, RECT rc, int grad, int frame, EDirect eDir, RGBTRIPLE* rgb )  {  int x3,y3,x4,y4;  switch ( eDir )    {    case dirUp  :      x3 = rc.right+1,y3 = rc.bottom+1,x4 = rc.left-1,y4 = rc.bottom+1;      break;    case dirDown:      x3 = rc.left-1,y3 = rc.top-1,x4 = rc.right+1,y4 = rc.top-1;    break;    case dirVert:      x3 = rc.right+1,y3 = 10000,x4 = rc.left-1,y4 = 10000;    break;    case dirLeft :      x3 = rc.right+1,y3 = rc.top-1,x4 = rc.right+1,y4 = rc.bottom+1;      break;    case dirRight:      x3 = rc.left-1,y3 = rc.bottom+1,x4 = rc.left-1,y4 = rc.top-1;    break;    case dirHorz:      x3 = 10000,y3 = rc.top-1,x4 = 10000,y4 = rc.bottom+1;    break;    default:      return;    }  //  bool bVert = eDir == dirUp || eDir == dirDown || eDir == dirVert;  //  // Заливка области  CMyPen arc( hDC, 0 );  if ( grad > 1 )    {    HBRUSH hBrush = ::CreateSolidBrush(Rgb(rgb[0]));    if ( hBrush )      {      HBRUSH hUld = (HBRUSH) ::SelectObject( hDC, hBrush );      ::BeginPath( hDC );      ::Arc( hDC, rc.left, rc.top, rc.right, rc.bottom, x3,y3,x4,y4 );      ::EndPath( hDC );      ::StrokeAndFillPath( hDC );      ::SelectObject( hDC, hUld );      ::DeleteObject( hBrush );      }    }  //  POINT point;  ::GetViewportOrgEx( hDC, &point );  ::OffsetRect( &rc, point.x, point.y );  //  HRGN hRlu = NULL,hRrd = NULL;  if ( bVert )    {    hRlu = ::CreateRectRgn( rc.left, rc.top, (rc.right+rc.left)/2, rc.bottom );    hRrd = ::CreateRectRgn( (rc.right+rc.left)/2, rc.top, rc.right, rc.bottom );    }  else    {    hRlu = ::CreateRectRgn( rc.left, rc.top, rc.right, (rc.bottom+rc.top)/2 );    hRrd = ::CreateRectRgn( rc.left, (rc.bottom+rc.top)/2, rc.right, rc.bottom );    }  ::OffsetRect( &rc, -point.x, -point.y );  if ( hRlu != NULL && hRrd != NULL )    {    //    int part;    RECT rect = rc;    if ( bVert )      {      part = ( rc.right-rc.left )/grad;      ::InflateRect( &rect, -part, 0 );      }    else      {      part = ( rc.bottom-rc.top )/grad;      ::InflateRect( &rect, 0, -part );      }    //    for ( int n = 2; n < part; n++ )      {      //      if ( bVert )        ::InflateRect( &rect, 1, 0 );      else        ::InflateRect( &rect, 0, 1 );      //      {// Используем свойства локального стека для деструктора CMyPen      ::SelectClipRgn( hDC, hRlu );      CMyPen pen( hDC, Col(rgb[0],rgb[1],n,part) );      ::Arc( hDC, rect.left, rect.top, rect.right, rect.bottom, x3,y3,x4,y4 );      }      {// Используем свойства локального стека для деструктора CMyPen      ::SelectClipRgn( hDC, hRrd );      CMyPen pen( hDC, Col(rgb[0],rgb[2],n,part) );      ::Arc( hDC, rect.left, rect.top, rect.right, rect.bottom, x3,y3,x4,y4 );      }      ::SelectClipRgn( hDC, NULL );      }//for ( int n = 1; n < part; n++ )    // Повторно    if ( frame > 0 )    ::Arc( hDC, rc.left, rc.top, rc.right, rc.bottom, x3,y3,x4,y4 );    }  if ( hRlu != NULL ) ::DeleteObject(hRlu);  if ( hRrd != NULL ) ::DeleteObject(hRrd);  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintDnoE(DefinePaint)  {  QueueP(Queue_DnoE);  GradientEllipse( hDC, p->mRect, p->gr, p->fr, p->eDir, p->rgb );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddDnoE(DefineTegs)  {  AddQueueEx(Queue_DnoE);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintDnoE;  //  COLORREF fon   = 0xfffffe;//0-фон  COLORREF light = 0x888888;//1-свет  COLORREF dark  = 0x888888;//2-тьма  p->gr = 1;  //  STegObj obj[] =    {    { 'R', "rect"  , &p->mRect },    { 'E', "rc"    , &p->mRect },    { 'A', "fon"   , &fon   },    { 'A', "light" , &light },    { 'A', "dark"  , &dark  },    { 'A', "f"     , &fon   },    { 'A', "l"     , &light },    { 'A', "d"     , &dark  },    { 'I', "frame" , &p->fr },    { 'I', "g"     , &p->gr },    { 'I', "grad"  , &p->gr },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  p->eDir = ParserDirect(teg[0].value);  SetT(p->rgb[0],fon  );  SetT(p->rgb[1],light);  SetT(p->rgb[2],dark );  //  if ( fon == 0xfffffe )    {    p->rgb[0].rgbtRed = ((WORD)p->rgb[1].rgbtRed+(WORD)p->rgb[2].rgbtRed)/2;    p->rgb[0].rgbtBlue = ((WORD)p->rgb[1].rgbtBlue+(WORD)p->rgb[2].rgbtBlue)/2;    p->rgb[0].rgbtGreen = ((WORD)p->rgb[1].rgbtGreen+(WORD)p->rgb[2].rgbtGreen)/2;    }  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~